import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"阶段二至六交付状态","description":"记录当前已跑通的能力、验证证据、本地替代实现和明确留空的部分。","frontmatter":{"title":"阶段二至六交付状态","description":"记录当前已跑通的能力、验证证据、本地替代实现和明确留空的部分。","outline":[2,3]},"headers":[],"relativePath":"delivery/status.md","filePath":"delivery/status.md","lastUpdated":1794302657000}'),a={name:"delivery/status.md"};function n(c,t,i,l,s,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="阶段二至六交付状态" tabindex="-1">阶段二至六交付状态 <a class="header-anchor" href="#阶段二至六交付状态" aria-label="Permalink to &quot;阶段二至六交付状态&quot;">​</a></h1><p>核对日期：2026-11-10。本文只记录当前代码和真实运行能证明的事实，不以页面存在代替闭环。</p><h2 id="阶段结论" tabindex="-1">阶段结论 <a class="header-anchor" href="#阶段结论" aria-label="Permalink to &quot;阶段结论&quot;">​</a></h2><ul><li><strong>阶段二：部分完成。</strong> 本地文件、知识库、公开网页、文档表格提取、任务来源引用，以及“草稿 → 审批 → 本地发件箱写入 → 回执”的闭环已可用；IMAP 只读同步和 SMTP 发送已形成代码闭环，但需要用户配置真实账户并完成人工验收。日历账户和真实邮件服务商的退信/垃圾邮件语义仍未验收，因此不能宣称阶段二整体验收完成。</li><li><strong>阶段三：部分完成。</strong> 同机 Windows 设备已能配对、逐项审批能力、开始观察、暂停、继续、接管、交还、终止，并在明确目标应用后执行低风险点击、输入、按键和 UIAutomation 动作。敏感区域遮挡、隔离桌面、高风险动作、快照与补偿仍未实现，因此不能宣称阶段三整体验收完成。</li><li><strong>阶段四：部分完成。</strong> 主动建议、主动收件箱、接受/忽略/稍后提醒/转任务、注意力预算、暂停入口、应用内通知和飞书长连接审批已形成代码闭环；Web 端已有可安装 PWA 壳、离线应用壳和移动底部导航。手机配对、系统级推送、远程接管及 iOS/Android 真机验收仍未完成，因此不能把阶段四称为完整交付。</li><li><strong>阶段五：部分完成。</strong> 记忆候选、召回、纠正、冲突、遗忘传播、导出，候选方法的生成、试跑证据、评估、晋升、拒绝和回退，以及 5.12 的持久委派、可审阅 Handoff、沙箱和渠道边界已形成代码闭环；5.11–5.13 共加入 30 个本地可重复场景，其中 10 个为 Personal Agent 专项场景，并保留 P0 故障注入回归。真实长期记忆使用、方法采用前后的生产对照、完整 5.4 验收、真实多执行器压力与真实渠道/设备场景尚未完成。</li><li><strong>阶段六：部分完成。</strong> 增量事件同步、同步对端认证、冲突处理、任务租约与 epoch fencing、设备撤销与令牌轮换、kill switch、加密数据库备份恢复、健康检查、维护和脱敏诊断已形成代码闭环；连接运行时已分离 transport、subscription、dataFreshness 和 executionOwnership，并提供 generation 隔离、离线 outbox、设备能力扩权审批和远程动作 uncertain 对账。真实双设备切换、真实远程节点断网恢复、设备丢失演练、完整迁移、数周连续运行和 v1.0 发布验收尚未完成。</li></ul><h2 id="体验补齐-2026-11-08" tabindex="-1">体验补齐（2026-11-08） <a class="header-anchor" href="#体验补齐-2026-11-08" aria-label="Permalink to &quot;体验补齐（2026-11-08）&quot;">​</a></h2><p>本轮补齐的是用户可感知的入口和最后一公里，不改变原有任务、审批和恢复边界：</p><ul><li><strong>首次运行：</strong> 全新实例进入 <code>/welcome</code> 四步向导，完成服务商选择、连接测试、聊天模型保存、原生执行器绑定、记忆/主动偏好；向导失败时 fail-open，不阻塞其他路由。</li><li><strong>记忆与主动：</strong> 主导航重新暴露“需要你”和“记忆”；记忆默认由向导开启“任务经历”候选，直答聊天会召回已确认记忆并显示参考条数；任务成功、失败和可恢复终态都会尝试捕获经历。</li><li><strong>主动提醒：</strong> 主动服务启动后扫描一次，之后每 5 分钟扫描，并响应任务/审批/效果/来源事件；页面内 toast 和可选桌面通知只负责“让人看到”，页面关闭后不承诺推送。</li><li><strong>飞书：</strong> 企业自建应用长连接、open_id 白名单、文本/图片/文件消息、任务状态转发、审批摘要和 <code>/approve</code>、<code>/reject</code> 文本命令已形成代码闭环。飞书卡片按钮回调不支持长连接，首版不做卡片按钮。</li><li><strong>邮件：</strong> SMTP 发送复用效果账本，审批预览写明真实发送和不可撤回；IMAP 只读同步最近邮件到来源，不标记已读。邮件工作台提供账户、收件箱和写信；首版不支持附件选择。</li><li><strong>尚未验收：</strong> 真实飞书租户、真实 SMTP/IMAP 账户、退信与垃圾邮件语义、页面关闭后的推送、邮件附件 UI，以及真实用户长期使用。</li></ul><h2 id="与-t3-code-的能力差距收窄-2026-11-09" tabindex="-1">与 T3 Code 的能力差距收窄（2026-11-09） <a class="header-anchor" href="#与-t3-code-的能力差距收窄-2026-11-09" aria-label="Permalink to &quot;与 T3 Code 的能力差距收窄（2026-11-09）&quot;">​</a></h2><p>本轮优先补齐与 Hearth 任务所有权、审批账本和日常使用直接相关的入口，不把 Hearth 改造成 IDE：</p><ul><li><strong>交互粒度：</strong> 任务运行中可以追加“轮后继续”或“中止当前轮并带补充重跑”。<code>queue</code> 不打断当前轮；<code>steer</code> 会中止当前轮、保留任务与产物，再用补充信息重跑，不是向正在生成的 token 流中实时注入。</li><li><strong>工具审批：</strong> <code>@hearth/agent-runtime</code> 在执行敏感工具前调用调度器审批桥；写文件、改文件、应用补丁、运行命令、联网读取和桌面截图在必要审批下进入 <code>waiting_approval</code>，批准后继续，拒绝后以工具错误回给模型并继续任务。DeepSeek Harness 的 SDK <code>approval/request</code> 也进入同一审批记录，分别映射为 <code>allowed-once</code>、<code>rejected</code> 和 <code>cancelled</code>。原生执行器的完全权限不打断，但写入 <code>approval.auto_approved</code> 审计事件；DeepSeek Harness 在完全权限下收到审批请求时也自动放行并写审计。外部 effect 仍走原有参数指纹、效果账本和回执，两层审批不合并。</li><li><strong>Git 工作台：</strong> 任务详情展示工作区与相对基线的文件 diff、增删行数、提交、文件源码预览、PR 与 CI 检查状态；即使工作区有未提交改动，也能独立查看分支相对基线的改动。</li><li><strong>快速入口与移动壳：</strong> 增加 <code>Ctrl/Command + K</code> 页面与任务跳转、PWA Manifest、应用图标、离线应用壳和移动底部导航。</li><li><strong>任务整理：</strong> 任务列表支持置顶、归档和恢复；归档任务默认从“全部”“进行中”“已完成”“需要处理”中隐藏，可在“已归档”筛选中找回，置顶任务优先显示。整理状态写入独立的 <code>pinnedAt</code>/<code>archivedAt</code> 字段，不改变任务状态、审批、租约或执行结果。</li></ul><p><strong>仍明确留空：</strong> Codex、Hermes、Qoder、WorkBuddy、Kimi 等外部执行器还没有把 provider 原生逐次审批事件统一接回 Hearth；没有任意 project/worktree 管理、隐藏 ref 文件回滚、PR 评审决定/自动合并/revert、subagent、MCP 服务端或 provider 原生 skills/commands。PWA 仍未完成 iOS/Android 真机安装、系统推送、手机配对和远程接管验收。</p><h2 id="agent-运行时闭环" tabindex="-1">Agent 运行时闭环 <a class="header-anchor" href="#agent-运行时闭环" aria-label="Permalink to &quot;Agent 运行时闭环&quot;">​</a></h2><ul><li><strong>已实现：</strong> 原生执行器 <code>native</code> 与工程执行器 <code>codex</code> 并列，执行器身份写入运行记录和产物清单；普通任务默认走原生执行器，明确的代码/工程任务走 Codex，失败后不静默切换。</li><li><strong>已实现：</strong> 四协议模型接入（OpenAI Chat、OpenAI Responses、Anthropic Messages、Gemini），统一流式文本与工具调用；服务商可在设置中选择或自定义。</li><li><strong>已实现：</strong> <code>@hearth/agent-runtime</code> 单 Agent 工具循环，包含读取、搜索、写入、编辑、补丁、命令、联网、询问用户和完成工具；任务级读写目录、网络域名和工具白名单。</li><li><strong>已实现：</strong> 轮次、工具次数、Token 和时长预算；每个模型回合与工具步骤写检查点；等待用户补充时可带着回答恢复；缺失产物时带上一轮 Agent 上下文补交，最多两轮。</li><li><strong>已实现：</strong> 需要联网或工程工作区权限的任务先在聊天中生成提案，用户确认后才创建任务；普通通用任务直接派出。</li><li><strong>界面结果：</strong> 任务页显示执行器、阶段、Token、耗时和结果；详情页默认只展示用户需要的总结与声明产物，中间 JSON、命令日志和检查点收进折叠区域。</li></ul><p>以上是代码与自动测试能证明的闭环，不代表已在真实用户环境中完成长期运行验收。</p><h2 id="阶段二能力" tabindex="-1">阶段二能力 <a class="header-anchor" href="#阶段二能力" aria-label="Permalink to &quot;阶段二能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小阶段</th><th>当前状态</th><th>已实现</th><th>明确留空</th></tr></thead><tbody><tr><td>2.1 只读信息源</td><td>部分完成</td><td>本地文件、知识库、公开网页来源；域名白名单；来源状态、读取时间、错误、增量读取、去重、断开、重连和清除；IMAP 只读同步最近 20–50 封到来源</td><td>日历只显示“待配置”；邮件真实账户、权限和限频仍未人工验收</td></tr><tr><td>2.2 文档、表格与网页资料</td><td>已实现基础闭环</td><td>TXT、Markdown、CSV、JSON、HTML、PDF、DOCX、XLSX 文本提取；页码、段落、工作表、范围和缺口记录；网页快照与来源条目可回看</td><td>复杂版式、扫描件 OCR、逐页引用定位和表格公式保真未实现</td></tr><tr><td>2.3 起草、审批与外部写入</td><td>部分完成</td><td>草稿可编辑、保存、丢弃；提交后生成一次性、短时有效审批；默认写入本地发件箱；选择 <code>smtp:&lt;accountId&gt;</code> 时生成真实发送审批，批准后通过 SMTP 发送并保存回执；拒绝或失效会同步草稿状态</td><td>默认仍写本机；真实 SMTP 账户、退信语义和日历写入未验收；首版邮件 UI 不支持附件选择</td></tr><tr><td>2.4 日常内容工作验收</td><td>未完成</td><td>已有自动测试和隔离实例上的本地来源、提取、发件箱链路验证</td><td>尚未用 10–15 个真实日常任务完成时间、准确率、恢复能力和用户意愿验收</td></tr></tbody></table><p>阶段二的本地发件箱不是“假成功”：界面明确显示只写入本机、不发送给收件人。真实邮件账户接入前，不应把该状态称为已发送。</p><h2 id="阶段三能力" tabindex="-1">阶段三能力 <a class="header-anchor" href="#阶段三能力" aria-label="Permalink to &quot;阶段三能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小阶段</th><th>当前状态</th><th>已实现</th><th>明确留空</th></tr></thead><tbody><tr><td>3.1 连接并查看桌面设备</td><td>部分完成</td><td>六位配对码、设备令牌、配对审批与能力审批分离；观察、控制、界面自动化逐项授权；应用白名单；在线状态和撤销设备</td><td>尚未实现托盘或全局常驻的“自动控制中”提示；仅 Windows 同机助手</td></tr><tr><td>3.2 观察桌面与人工接管</td><td>部分完成</td><td>截图绑定当前会话；暂停、继续、接管、交还、终止；接管会取消待执行输入并推进控制代次；用户输入空闲检查；截图 2 分钟过期</td><td>敏感区域遮罩、长期录像、完整桌面快照未实现</td></tr><tr><td>3.3 分级完成桌面操作</td><td>部分完成</td><td>目标应用绑定与执行前聚焦复核；点击、短文本、Enter/Tab/Escape/Ctrl+S；UIA invoke/setvalue 白名单；UWP 宿主窗口通过 UIA 子进程映射到批准应用；命令状态和结果记录；不支持动作结构化拒绝</td><td>高风险动作预览与二次确认、隔离桌面、快照、补偿、真实 UIA setvalue 验收未完成</td></tr><tr><td>3.4 桌面操作验收</td><td>未完成</td><td>已在隔离端口完成配对、能力审批、观察、暂停、继续、接管、交还和专业版展开验证</td><td>尚未用至少 5 个真实桌面任务完成成功率、接管次数和失败演练验收</td></tr></tbody></table><p>Windows 助手目前采用“先聚焦服务端批准的目标应用，再截图或输入”的方式，不适合后台无焦点操作。对于由 <code>ApplicationFrameHost</code> 承载窗口的 UWP 应用，助手会读取窗口的 UIA 子树，只有解析出与批准应用对应的子进程时才允许聚焦和观察；例如 <code>CalculatorApp</code> 会映射为批准名 <code>calculator</code>。无法唯一归属或无法读取 UWP 子进程时直接拒绝，不把整个宿主窗口静默当成目标。真实 UIA invoke 已在计算器中验证：调用“二”返回 <code>InvokePattern</code>，读数由 <code>7</code> 变为 <code>72</code>。同一条链路也已在隔离配对设备上完成“观察 → UIA 动作 → 自动观察”，命令结果和截图回传均成功。</p><h2 id="阶段四能力" tabindex="-1">阶段四能力 <a class="header-anchor" href="#阶段四能力" aria-label="Permalink to &quot;阶段四能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小阶段</th><th>当前状态</th><th>已实现</th><th>明确留空</th></tr></thead><tbody><tr><td>4.1 触发条件与主动建议</td><td>已实现代码闭环</td><td>六类触发器：任务进入 24 小时截止窗口、任务失败或可恢复、外部动作结果不确定、审批等待超过 2 小时、来源在 24 小时内出现新条目、队列积压或任务长时间运行；建议包含来源、为什么现在重要、建议动作、预计影响、预计成本、风险、是否需要审批和优先级；同一事件按键去重并累计出现次数</td><td>邮件和日历触发器只有禁用占位，没有账户读取；主动模式只生成建议，不直接执行高风险动作</td></tr><tr><td>4.2 主动收件箱</td><td>已实现代码闭环</td><td>独立收件箱按优先级展示建议；支持接受、忽略、稍后提醒和转成普通任务；接受与转任务分离；应用内 toast、可选桌面通知和飞书长连接可分发“需要你”的审批/建议；忽略后同一事件不换说法继续推送</td><td>页面关闭后没有系统级推送；手机收件箱和远程接管仍未实现</td></tr><tr><td>4.3 手机查看、审批与接管</td><td>部分完成</td><td>飞书长连接支持手机文本/图片/文件消息、任务状态和一次性审批文本命令；open_id 白名单限制访问；Web PWA 提供 Manifest、应用图标、离线应用壳和移动底部导航</td><td>尚未完成 iOS/Android 真机安装验收；没有手机配对、系统级推送、卡片按钮或完整远程接管</td></tr><tr><td>4.4 注意力预算与主动服务验收</td><td>部分完成</td><td>每日上限 0–50、安静时段、冷却时间、聚合窗口、临时暂停和恢复；预算快照显示今日已用、限额、是否安静/暂停及下次允许时间；最近 7 天记录送达、接受、忽略、转任务和完成任务数；“需要你”页面集中显示待处理审批</td><td>尚未用 5–10 个真实主动任务验收“平均每个任务打断不超过一次”；没有推送送达统计，也没有长期用户感受记录</td></tr></tbody></table><p>阶段四的关键边界是“建议不等于执行”。<code>accept</code> 只改变建议状态；只有 <code>convert</code> 会创建一个新的排队任务，之后仍按普通任务的执行器、审批和效果账本规则运行。高风险动作不会因为来自主动建议而绕过审批。</p><h2 id="阶段五能力" tabindex="-1">阶段五能力 <a class="header-anchor" href="#阶段五能力" aria-label="Permalink to &quot;阶段五能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小阶段</th><th>当前状态</th><th>已实现</th><th>明确留空</th></tr></thead><tbody><tr><td>5.1 可查看的记忆</td><td>已实现代码闭环</td><td>记忆先进入候选，确认后才参与召回；记录类型、主题键、范围、标签、来源、置信度、敏感度、有效期和版本；召回按任务匹配度评分并记录原因与使用审计；注入上下文带 <code>trusted=&quot;false&quot;</code> 和“不能扩大权限”的边界；支持召回条数与字符预算</td><td>自动捕获默认关闭，且只支持从终态任务捕获“经历”记忆；没有从邮件、网页或任意文档自动抽取用户事实</td></tr><tr><td>5.2 纠正、遗忘与导出</td><td>已实现代码闭环</td><td>纠正生成新版本并保留历史；同主题冲突不会静默覆盖，必须选择左侧、右侧或合并；遗忘会把当前记录改为墓碑，并脱敏历史版本、相关事件和召回审计中的匹配词；导出不包含已遗忘正文；敏感记忆默认不召回，<code>secret</code> 记忆永不召回</td><td>跨设备遗忘只通过同步过滤和本地副本边界保证；没有对已导出到外部文件的旧副本进行远程擦除</td></tr><tr><td>5.3 总结并评估可复用方法</td><td>已实现代码闭环</td><td>从终态任务轨迹生成候选；权限取来源任务能力交集，候选不得扩大权限；基线/试跑记录成功率、耗时、token 和审批次数；评估区分 improved、flat、regressed、insufficient；只有有改进证据且完成试跑样本的候选才能晋升；支持拒绝、回退并保留原因和审计</td><td>“试跑”只读取已有终态轨迹作为证据，不会为评估自动再执行一次任务，因此不是实时 Shadow 执行器；没有真实生产方法的长期采用对照</td></tr><tr><td>5.4 记忆与进化验收</td><td>未完成</td><td>已有 API、服务层和页面闭环测试，覆盖创建、确认、召回、纠正、冲突、遗忘、导出、试跑、晋升和回退</td><td>尚未完成真实用户的错误记忆演练、错误方法演练、采用前后成功率/人工时间/成本对照，以及完整“提出—评估—试用—采用—退回”生产验收</td></tr><tr><td>5.5 失败分类与只恢复已证明阶段</td><td>已实现代码闭环</td><td>失败按类别记录处置；检查点保存可验证的阶段证明边界；维护和调度只从已证明阶段恢复，不重放未知外部 effect；场景包覆盖崩溃恢复和未知 effect 对账</td><td>尚未用真实进程崩溃、真实执行器中断和长时间运行演练验证所有失败分类</td></tr><tr><td>5.6 Memory tier / provenance / taint / consolidation</td><td>已实现代码闭环</td><td>记忆记录 trust、taint、来源和派生关系；低信任网页内容不能写入 curated core 或进入召回包；支持 always-on/on-demand 车道、整合报告、版本脱敏和来源遗忘传播</td><td>尚未完成真实长期记忆、跨设备遗忘和已导出副本擦除的生产验收</td></tr><tr><td>5.7 Skill Package 与 Curator</td><td>已实现代码闭环</td><td>方法可导出为带 manifest 的技能包；工具、读写根和网络权限取来源任务交集；技能有 adopted/stale/archived 生命周期、pin、归档备份和 rollback；Curator 不静默删除技能</td><td>尚未完成真实技能包在外部 Agent 运行时的采用对照和长期维护验收</td></tr><tr><td>5.8 Standing Intents、Heartbeat 与注意力预算</td><td>已实现代码闭环</td><td>支持意图 scope、触发词、冷却、每日预算、安静时段、去重和 NO_REPLY；只有实际投递的注意力事项才调用通知器；主动提醒仍回到普通任务/审批链</td><td>尚未用真实用户完成 5–10 个主动任务的打扰率和漏报验收</td></tr><tr><td>5.9 调度器可靠性</td><td>已实现代码闭环</td><td>同一计划时刻最多一次运行；支持 catch-up 策略、DST 重复墙钟去重、失败退避/冷却和审批暂停；场景包覆盖补跑、DST 和取消后不再触发</td><td>尚未在真实时区和长期运行中验证全部 cron/DST 边界及进程重启组合</td></tr><tr><td>5.10 连接运行时与离线投影</td><td>已实现代码闭环</td><td>实现与证据见 6.5：owner connection、generation fencing、cached/asOf/cursor、离线 outbox、远程动作 uncertain 和 scope 隔离</td><td>见 6.5：尚未接入真实远程节点、手机和跨节点离线对账</td></tr><tr><td>5.11 个人 Agent 评估与回归体系</td><td>已迁出主仓库</td><td>30 个本地可重复场景、60 个评测 case、全周期评测控制台、评分复核与实验对比已迁移到独立仓库 <a href="https://github.com/hearthproject/hearth-eval" target="_blank" rel="noreferrer">hearth-eval</a>；场景覆盖提醒回环、审批拒绝、动作绑定、非交互高危、未知 effect、目标完成、崩溃恢复、记忆污染/遗忘、技能生命周期、主动噪声、调度补跑/DST、离线一致性、敏感信息，以及 10 个 Personal Agent 专项场景；主仓库只保留评测任务与裁判桥接</td><td>真实模型 provider、真实账户、真实设备和数周运行数据仍需在独立仓库中实际执行；场景通过不能替代人工验收，也不能用模型 judge 替代事实验证</td></tr><tr><td>5.12 持久委派、交接、沙箱与渠道边界</td><td>已实现代码闭环</td><td>单层委派 Job 支持幂等 key、lease、heartbeat、取消传播、父任务验收和 orphan recovery；子任务权限必须为父任务子集，父任务未声明权限时默认空工具；取消后效果守卫拒绝新副作用。Handoff 包持久目标、验收、权限、预算、证据和下一步，宿主校验通过后发布真实 <code>HANDOFF.md</code> 产物并记录 <code>artifactRef</code>；generation fence 拒绝旧代次工具写入，同时保留失败运行自己的诊断/决策证据。Sandbox 对路径逃逸、网络越界、进程/工具越权和凭据过期返回明确 failure class。飞书入站接入持久 ChannelIngressService，支持 externalId 幂等、ack/fail、可重试失败重投和上游时间游标；重连后的旧消息不会覆盖新状态。5 个边界场景各重复 3 次全部通过</td><td>当前只支持单层委派；Docker、SSH、VM、remote-worker 后端尚未实现；没有真实多执行器并发压力、真实飞书租户重连/限频、真实跨 Provider 长任务交接和凭据轮换验收</td></tr><tr><td>5.13 个人本体、上下文连续性与注意力治理</td><td>已实现代码闭环</td><td>SQLite schema v28 增加实体、别名、关系、状态、决定、承诺、提及、Context Pack、记忆-实体链接、任务边、预备动作、后台工具、线程订阅、看门狗和 Intake 决策。聊天、任务、审批和来源写回个人状态；实体与状态支持四档置信度、冲突注意力、用户纠正和按证据遗忘。Context Broker 提供四 lane、稳定 ref、预算、敏感度、taint、trust、有效期、<code>expand_ref</code> 和委派父包继承；Mention Resolver 对歧义指代提问并阻断不可逆动作。Attention Governor 统一候选、预算、解释与反馈，Inbox 以注意力事项为主模型。原生执行器新增 <code>get_entity</code>、<code>get_entity_state</code>、<code>get_relations</code>、<code>get_decision</code>、<code>list_commitments</code> 五个只读工具。Task DAG 支持深度、子任务和并行上限，<code>all</code>/<code>any</code>/<code>n_of_m</code> 汇聚与取消传播。预备动作、后台工具、线程订阅、Watchdog 与 Intake 均有 API 和 <code>/runtime</code> 控制面，<code>/personal</code> 提供实体、承诺、决定、纠正和遗忘操作</td><td>场景与本地隔离数据证明机制，不证明真实用户长期价值；实体解析只在单场景 ground truth 上验证；<code>human_minutes_saved</code> 是显式建模值；生产阈值仍需 2 周 dogfooding 基线校准</td></tr></tbody></table><p>记忆与方法的共同边界是“先候选、后确认；先证据、后晋升”。候选方法不会自动上线，记忆内容也不能作为指令直接扩大工具、网络或审批能力。</p><h2 id="personal-agent-升级-2026-11-10" tabindex="-1">Personal Agent 升级（2026-11-10） <a class="header-anchor" href="#personal-agent-升级-2026-11-10" aria-label="Permalink to &quot;Personal Agent 升级（2026-11-10）&quot;">​</a></h2><p>本轮以 <code>codex/eval-agent</code> 的实际代码为基线，把任务系统扩展为可持续的个人 Agent 层，没有重写执行面，也没有引入常驻 LLM Router：</p><ul><li><strong>个人状态层：</strong> 10 类实体、别名、关系和状态、决定、承诺、提及与证据引用进入 SQLite schema v28。实体和状态使用 <code>confirmed / observed / inferred / stale</code> 四档置信度；同一字段出现来源冲突时生成冲突注意力事项，不静默覆盖。</li><li><strong>写回与遗忘：</strong> 聊天确认、任务完成、审批决定和来源入库都会尝试写回本体；用户纠正生成新的确认状态和用户决定。遗忘按证据引用传播到实体、别名、关系、状态、决定、承诺、记忆和 Context Pack，并保留可审计墓碑。</li><li><strong>上下文连续性：</strong> Context Broker 生成 <code>must_know / relevant / recallable / omitted</code> 四 lane 上下文包，注入项带稳定 ref、来源、置信度、有效期和原因；支持 token 预算、敏感度、taint、trust、<code>expand_ref</code> 以及委派子包继承父包边界。</li><li><strong>指代与歧义：</strong> Mention Resolver 将“昨天那个”“小艾”等表述解析到实体或决定；多个候选时要求澄清，不可逆外部动作在歧义未解决前直接阻断。</li><li><strong>注意力治理：</strong> Attention Governor 统一任务、审批、承诺、对账、来源、冲突和主动建议候选；预算、安静时段、冷却、去重和影子模式仍按原有治理边界运行。每条投递可解释，Inbox 以“现在需要你决定什么”为主列表，并记录接受、忽略、稍后和错误反馈。</li><li><strong>任务图与异步执行：</strong> Task DAG 默认最大深度 3、每个父任务最多 5 个子任务、最多 3 个并行；支持 <code>all</code>、<code>any</code>、<code>n_of_m</code> 汇聚、循环拒绝和取消失败传播。后台工具支持启动、输出、停止和审批；预备动作只允许只读或可丢弃预览，外部副作用必须绑定同一任务的审批和动作摘要。</li><li><strong>运行可观测性：</strong> 线程订阅把执行器事件回流到任务，忽略自身订阅事件以避免递归；Watchdog 支持重复失败、超时和影子模式；Intake Router 对入站内容做 <code>ignore / chat / task / attention</code> 确定性分流并记录决策。</li><li><strong>原生执行器：</strong> 除 <code>expand_ref</code> 外，新增五个只读本体查询工具；工具名通过权限合并进入原生运行时，但仍不扩大写目录、网络或审批权限。</li><li><strong>控制面：</strong> <code>/personal</code> 展示实体、状态、别名、承诺和决定，支持用户纠正、查看证据和按证据遗忘；<code>/runtime</code> 展示预备动作、后台工具、线程订阅、Watchdog 和 Intake 决策。</li><li><strong>PA 专项场景：</strong> 新增 <code>mention-ambiguous</code>、<code>cross-session-continue</code>、<code>stale-state-deadline</code>、<code>source-conflict-owner</code>、<code>attention-budget-30</code>、<code>forget-propagation-ontology</code>、<code>prompt-injection-ontology</code>、<code>four-week-continuity</code>、<code>task-dag-fan-in</code>、<code>async-tool-interrupt</code>，并纳入统一场景包。</li></ul><p>这一层的边界是：场景可以证明机制和故障边界，不能证明真实长期价值。生产阈值、真实用户注意力收益和实体解析总体准确率仍需用真实数据和 dogfooding 基线校准。</p><h2 id="阶段六能力" tabindex="-1">阶段六能力 <a class="header-anchor" href="#阶段六能力" aria-label="Permalink to &quot;阶段六能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小阶段</th><th>当前状态</th><th>已实现</th><th>明确留空</th></tr></thead><tbody><tr><td>6.1 多设备同步与切换</td><td>部分完成</td><td>每个实例有独立 <code>instanceId</code>；同步对端令牌只显示一次，服务端保存哈希和加密副本；按事件序号增量拉取并去重；导入事件可重建投影；任务、记忆和方法的较新本地状态不会被远端静默覆盖，冲突保留双方记录并由用户选择 local/remote；同步 UI 展示对端、游标、错误和冲突</td><td>只同步经过过滤的事件投影；审批、来源、发件箱、设备、桌面、安全、同步事件以及敏感/机密记忆不会复制；产物正文、工作区和本地绝对路径不会同步；尚未用两台真实设备完成切换和断网恢复验收</td></tr><tr><td>6.2 设备撤销与安全迁移</td><td>部分完成</td><td>任务租约带 TTL、owner、epoch；过期后其他实例可接管并推进 epoch，旧 owner 的提交和结果会被拒绝；设备能力可撤销、设备令牌可轮换、设备可重新配对；同步对端可轮换令牌或撤销；全局 kill switch 会阻止审批和调度器重启，并记录安全审计；安全页展示状态与审计</td><td>没有专门的跨设备产物/工作区迁移流程；没有真实设备丢失演练来证明旧设备在撤销后无法审批、接管或读取；解除全局停止后不会自动恢复执行器，需要用户显式重启</td></tr><tr><td>6.3 备份、恢复与升级</td><td>部分完成</td><td>生成 <code>*.hearth-backup</code> 加密归档；口令经 scrypt（N=32768、r=8、p=1）派生，AES-256-GCM 加密，口令至少 12 字符；归档包含 SQLite 快照、必要设置/审计/事件元数据和加密后的本机 <code>master.key</code>；恢复先写临时 SQLite，检查 <code>user_version</code>、schema 和 <code>integrity_check</code>，重建投影，再事务复制，失败回滚；保留当前实例 <code>instanceId</code>、<code>createdAt</code> 和全局停止状态，清除旧租约、配对和桌面会话临时记录；旧 <code>/api/backup</code> 返回 <code>410</code> 并要求使用加密备份</td><td>不包含产物正文、任务工作区、来源正文、发件箱附件、截图/桌面临时文件和外部服务数据，因此不是完整可迁移备份；没有应用版本升级流水线或升级失败回退发布流程；schema 不兼容会拒绝恢复，但没有真实跨版本 fixture 演练</td></tr><tr><td>6.4 长期运行与 v1.0 验收</td><td>部分完成</td><td>健康快照包含运行时长、内存、磁盘、schema、任务计数、调度器、审批、kill switch 和最近一次维护；维护会清理过期审批、恢复中断任务、删除过期租约/桌面命令/截图/配对和临时文件，不删除任务、记忆或产物；服务启动后每 6 小时自动维护，也可手动触发；维护失败会记录失败并把健康状态标为 degraded；诊断导出包含健康、维护、计数和事件类型，不含路径、密钥或环境秘密；运维页展示健康、维护和备份边界</td><td>没有数周连续运行测试、资源漂移数据、真实 v1.0 安装/升级/迁移/退出验收，也没有完整的全任务类型回归矩阵</td></tr><tr><td>6.5 连接运行时与离线投影</td><td>已实现代码闭环</td><td>每个设备与用户有 owner connection；<code>transport</code>、<code>subscription</code>、<code>dataFreshness</code> 和 <code>executionOwnership</code> 分开返回；重连推进 generation，旧代次写入被拒绝；投影标记 <code>cached</code>、<code>asOf</code>、<code>sourceCursor</code> 和 <code>latestCursor</code>，缓存不会冒充实时；离线操作只进入 connection outbox；远程动作断线后进入 <code>uncertain</code> 并要求显式对账；设备能力扩权必须再次审批，设备撤销后立即拒绝读取和执行</td><td>尚未接入真实远程节点或手机；连接 API 目前仍受本机访问限制，未增加设备 bearer token；没有真实断网重连、长期离线缓存、跨节点 outbox 对账和客户端 UI 验收</td></tr></tbody></table><p>阶段六的备份边界需要在界面上继续显示：数据库可恢复不等于产物文件可迁移。恢复完成后，任务可能重新出现，但产物正文、任务工作区或外部附件仍需要单独备份和核对。</p><h2 id="借鉴与取舍" tabindex="-1">借鉴与取舍 <a class="header-anchor" href="#借鉴与取舍" aria-label="Permalink to &quot;借鉴与取舍&quot;">​</a></h2><ul><li><strong>OpenClaw：</strong> 配对与能力审批分离；命令按设备声明并逐项授权；观察帧是动作的唯一依据；用户接管会取消待执行输入、推进控制代次；不支持的动作直接拒绝。Hearth 已采用这些边界。</li><li><strong>Hermes：</strong> 强调显式能力清单、执行前目标复核和会话隔离。Hearth 已采用应用白名单、目标应用复核和控制代次；尚未采用后台无焦点输入，因为当前 Windows 执行层无法可靠证明输入仍落在批准窗口内。</li><li><strong>OpenClaw 的主动服务思路：</strong> 建议与执行分离、建议动作仍回到普通审批链。Hearth 已采用；没有把主动建议做成自动执行器。</li><li><strong>Hermes 的健康检查思路：</strong> 把驱动、权限、运行状态和最近维护结果显式暴露。Hearth 已用健康快照、维护记录和脱敏诊断采用该边界。</li><li><strong>DeerFlow：</strong> 任务拆解、方法候选和评估分层只作为设计参考。Hearth 没有集成 DeerFlow，也没有引入其多 Agent 运行时。</li><li><strong>LoopX：</strong> 只借鉴小闭环提交、状态证据和验收边界作为交付方法；没有把 LoopX 作为运行依赖。</li><li><strong>T3 Code / OpenClaw 的连接运行时：</strong> 采用 owner connection、generation fencing、传输/订阅/新鲜度分离、离线 outbox 和重连不自动重放 mutation 的边界；没有复制其协议、会话存储或客户端实现。</li></ul><h2 id="验证证据" tabindex="-1">验证证据 <a class="header-anchor" href="#验证证据" aria-label="Permalink to &quot;验证证据&quot;">​</a></h2><p>2026-11-10 在当前分支运行 <code>npm test</code>，89 个测试文件、579 个测试全部通过；<code>npm run typecheck</code>、<code>npm run build</code> 和 <code>npm run docs:build</code> 通过。测试覆盖服务层、API、模型协议、原生工具循环、预算、权限、检查点、提案确认、记忆/技能治理、主动提醒、调度、连接运行时、持久委派、交接产物、沙箱分类、渠道幂等、个人本体、Context Broker、任务图和只读本体工具，但不替代真实用户、真实设备和长期运行验收。</p><p>个人 Agent 的场景回归、评测 case、实验结果和指标证据已迁移到独立仓库 <a href="https://github.com/hearthproject/hearth-eval" target="_blank" rel="noreferrer">hearth-eval</a>。该仓库负责 30 个白盒场景、60 个 case、评测控制台、评分复核和真实实验；主仓库不再保留 <code>eval/scenarios</code>、<code>eval/scenario-runs</code> 或评测数据库。本轮文档更新没有代替用户运行真实评测实验。</p><p>同日刷新 README 与文档站首页截图：<code>npm run screenshots:readme</code> 在随机端口启动隔离实例，使用临时 <code>HEARTH_DATA_DIR</code> 写入演示任务、审批建议和记忆，再通过 Playwright 生成中文浅色界面截图；脚本不读取或修改真实 <code>.hearth</code> 数据。</p><h2 id="尚未完成的真实验收" tabindex="-1">尚未完成的真实验收 <a class="header-anchor" href="#尚未完成的真实验收" aria-label="Permalink to &quot;尚未完成的真实验收&quot;">​</a></h2><ol><li>真实 SMTP/IMAP 账户、真实发送回执、退信与垃圾邮件语义；日历账户仍未接入。</li><li>10–15 个日常内容任务，以及至少 5 个桌面任务的完整验收记录。</li><li>敏感区域遮罩、隔离桌面、快照、补偿和高风险操作。</li><li>真实应用中的 UIA setvalue 验收，以及窗口丢失、权限变化和用户接管的失败演练。</li><li>真实飞书租户、长连接重连与限频、卡片按钮后续方案；手机 PWA、配对、系统级推送和远程接管；5–10 个真实主动任务的打扰验收。</li><li>阶段五错误记忆/错误方法演练、完整导出核对，以及候选方法采用前后的真实生产对照。</li><li>阶段六真实双设备同步、断网恢复、设备丢失撤销、令牌轮换、备份恢复和迁移核对；连接运行时的真实远程节点、手机断网重连和跨节点 outbox 对账。</li><li>至少数周连续运行、资源与状态漂移检查、版本升级回退流水线和 v1.0 整体验收。</li></ol><p>这些缺口已经留空，不用模拟数据或“看起来完成”的界面替代。</p>',42)])])}const p=e(a,[["render",n]]);export{u as __pageData,p as default};
